agent_detail.agent_sql:
SELECT (COUNT(?c) AS ?n) WHERE {
  ?c a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim> .
}

SELECT (SUM(?claim_amount) AS ?expensePaymentAmount) ?company_claim_number
WHERE {
  ?ep a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ExpensePayment> ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ExpensePayment/hasClaimAmount> ?ca .
  ?ca a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount> ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?claim_amount ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/hasClaim> ?claim .
  ?claim a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim> ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/company_claim_number> ?company_claim_number .
}
GROUP BY ?company_claim_number

SELECT ?company_claim_number (SUM(?amount) AS ?total)
WHERE {
  ?claim a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim> ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/company_claim_number> ?company_claim_number ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/claim_identifier> ?claimId .
  ?ca a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount> ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_identifier> ?claimId ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount_identifier> ?caId ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?amount .
  {
    ?lp a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossPayment> ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossPayment/claim_amount_identifier> ?caId .
  }
  UNION
  {
    ?lr a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossReserve> ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossReserve/claim_amount_identifier> ?caId .
  }
}
GROUP BY ?company_claim_number

SELECT ?policy_number ?agent_id WHERE {
  ?policy a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy/policy_identifier> ?policy_id ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy/policy_number> ?policy_number .
  ?apr a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole> ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/agreement_identifier> ?policy_id ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_role_code> "AG" ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_identifier> ?agent_id .
}

SELECT ?company_claim_number WHERE {
  ?claim a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim> ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/claim_close_date> ?closeDate ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/company_claim_number> ?company_claim_number .
  FILTER(STRSTARTS(STR(?closeDate), "2019"))
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?lossPaymentAmount ?lossReserveAmount ?expensePaymentAmount ?expenseReserveAmount ?claim_number ?policy_number ?policyHolder ?premiumAmount ?agent
WHERE {
  ?claim a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim> ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/claim_identifier> ?claimId ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/company_claim_number> ?claim_number .

  ?cc a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage> ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage/claim_identifier> ?claimId ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage/policy_coverage_detail_identifier> ?pcdId .

  ?pcd a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyCoverageDetail> ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyCoverageDetail/policyCoverageDetailIdentifier> ?pcdId ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyCoverageDetail/policyIdentifier> ?policyId .

  ?policy a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy/policy_identifier> ?policyId ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy/policy_number> ?policy_number .

  ?aprPH a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole> ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/agreement_identifier> ?policyId ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_role_code> "PH" ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_identifier> ?policyHolder .

  ?aprAG a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole> ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/agreement_identifier> ?policyId ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_role_code> "AG" ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_identifier> ?agent .

  {
    SELECT ?policyId (SUM(?amt) AS ?premiumAmount)
    WHERE {
      ?prem a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Premium> ;
            <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Premium/policy_amount_identifier> ?paId .
      ?pa a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyAmount> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyAmount/policy_amount_identifier> ?paId ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyAmount/policy_identifier> ?policyId ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyAmount/policy_amount> ?amt .
    }
    GROUP BY ?policyId
  }

  {
    SELECT ?claimId (SUM(?amt) AS ?lossPaymentAmount)
    WHERE {
      ?lp a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossPayment> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossPayment/claim_amount_identifier> ?caId .
      ?ca a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount_identifier> ?caId ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_identifier> ?claimId ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?amt .
    }
    GROUP BY ?claimId
  }

  {
    SELECT ?claimId (SUM(?amt) AS ?lossReserveAmount)
    WHERE {
      ?lr a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossReserve> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossReserve/claim_amount_identifier> ?caId .
      ?ca a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount_identifier> ?caId ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_identifier> ?claimId ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?amt .
    }
    GROUP BY ?claimId
  }

  {
    SELECT ?claimId (SUM(?amt) AS ?expensePaymentAmount)
    WHERE {
      ?ep a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ExpensePayment> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ExpensePayment/claimAmountIdentifier> ?caId .
      ?ca a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount_identifier> ?caId ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_identifier> ?claimId ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?amt .
    }
    GROUP BY ?claimId
  }

  {
    SELECT ?claimId (SUM(?amt) AS ?expenseReserveAmount)
    WHERE {
      ?er a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ExpenseReserve> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ExpenseReserve/claim_amount_identifier> ?caId .
      ?ca a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount_identifier> ?caId ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_identifier> ?claimId ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?amt .
    }
    GROUP BY ?claimId
  }
}

SELECT ?company_claim_number (SUM(?amt) AS ?total)
WHERE {
  {
    ?lp a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossPayment> ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossPayment/claim_amount_identifier> ?caid .
  }
  UNION
  {
    ?lr a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossReserve> ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossReserve/claim_amount_identifier> ?caid .
  }
  UNION
  {
    ?ep a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ExpensePayment> ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ExpensePayment/claimAmountIdentifier> ?caid .
  }
  UNION
  {
    ?er a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ExpenseReserve> ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ExpenseReserve/claim_amount_identifier> ?caid .
  }
  ?ca a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount> ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount_identifier> ?caid ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?amt ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_identifier> ?cid .
  ?claim a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim> ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/claim_identifier> ?cid ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/company_claim_number> ?company_claim_number .
}
GROUP BY ?company_claim_number
ORDER BY ?company_claim_number

SELECT ?agent ?policyNumber ?catName WHERE {
  ?apr a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole> ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_role_code> "AG" ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_identifier> ?agent ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/hasPolicy> ?policy .

  ?policy a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy/policy_number> ?policyNumber .

  ?pcd a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyCoverageDetail> ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyCoverageDetail/hasPolicy> ?policy .

  ?cc a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage> ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage/hasPolicyCoverageDetail> ?pcd ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage/hasClaim> ?claim .

  ?claim a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim> ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/hasCatastrophe> ?cat .

  ?cat a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Catastrophe> ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Catastrophe/catastrophe_name> ?catName .
}

SELECT ?policy_number (AVG(?diffDays) AS ?avgSettleDays)
WHERE {
  ?claim a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim> ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/claim_open_date> ?open ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/claim_close_date> ?close .
  ?cc a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage> ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage/hasClaim> ?claim ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage/hasPolicyCoverageDetail> ?pcd .
  ?pcd <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyCoverageDetail/hasPolicy> ?policy .
  ?policy <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy/policy_number> ?policy_number .
  BIND(xsd:dateTime(?close) AS ?closeDT)
  BIND(xsd:dateTime(?open) AS ?openDT)
  BIND((?closeDT - ?openDT) AS ?diffDuration)
  BIND(xsd:decimal(?diffDuration) AS ?diffDays)
}
GROUP BY ?policy_number
ORDER BY ?policy_number

SELECT ?party_identifier (COUNT(?agreement_identifier) AS ?n) WHERE {
  ?apr a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole> ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_role_code> "AG" ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_identifier> ?party_identifier ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/agreement_identifier> ?agreement_identifier .
}
GROUP BY ?party_identifier

SELECT (?total / ?cnt AS ?avg)
WHERE {
  {
    SELECT (SUM(?amt) AS ?total) WHERE {
      ?pr a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Premium> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Premium/hasPolicyAmount> ?pa .
      ?pa <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyAmount/policy_amount> ?amt .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?p) AS ?cnt) WHERE {
      ?p a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy> .
    }
  }
}

